#!/usr/bin/env node
/**
 * Capture help-centre screenshots for every role.
 *
 * Boots a headless Chromium against a running app, signs in as each role's
 * demo user, and writes one full-page PNG per route into the configured output
 * directory as `<role>-<guideId>.png`. The guide data generated by
 * scaffold-help.mjs references these filenames, and verify-help.mjs fails if a
 * referenced file is missing — so re-run this after any UI change.
 *
 * Usage (from the target project root, with the stack already running):
 *
 *   node .agents/skills/help-centre/scripts/capture-screenshots.mjs
 *   HELP_CONFIG=./help.config.mjs node .../capture-screenshots.mjs
 *
 * Requires `playwright-core` plus a Chromium binary. Set CHROME_PATH to point
 * at one (default /usr/bin/chromium). Environment overrides: BASE_URL,
 * CHROME_PATH.
 */
import { chromium } from 'playwright-core';
import { mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const CONFIG_PATH = resolve(process.env.HELP_CONFIG || 'help.config.mjs');

async function loadConfig() {
  try {
    const mod = await import(pathToFileURL(CONFIG_PATH).href);
    return mod.default;
  } catch (err) {
    console.error(`Could not load help config at ${CONFIG_PATH}`);
    console.error('Copy assets/templates/help.config.mjs to the project root and edit it.');
    throw err;
  }
}

/** Sign in as one user. Selectors and the success URL come from the config. */
async function signIn(page, baseUrl, cfg, user) {
  await page.goto(`${baseUrl}${cfg.loginPath}`, { waitUntil: 'networkidle' });
  await page.fill(cfg.emailSelector, user.email);
  await page.fill(cfg.passwordSelector, user.password);
  await Promise.all([
    page.waitForURL(cfg.successPath, { timeout: 15000 }).catch(() => {}),
    page.click(cfg.submitSelector),
  ]);
  await page.waitForLoadState('networkidle').catch(() => {});
}

async function main() {
  const cfg = await loadConfig();
  const baseUrl = process.env.BASE_URL || cfg.baseUrl || 'http://localhost:3000';
  const outDir = resolve(cfg.outDir || 'public/help');
  mkdirSync(outDir, { recursive: true });

  // Optional hook: seed data so screenshots are not empty. Best-effort.
  if (typeof cfg.beforeCapture === 'function') {
    await cfg.beforeCapture({ baseUrl }).catch((err) =>
      console.warn('beforeCapture skipped:', err.message),
    );
  }

  const browser = await chromium.launch({
    executablePath: process.env.CHROME_PATH || '/usr/bin/chromium',
    args: ['--no-sandbox', '--disable-dev-shm-usage'],
  });

  const { width = 1440, height = 900 } = cfg.viewport || {};
  for (const [role, guides] of Object.entries(cfg.roles)) {
    const user = cfg.users?.[role];
    if (!user) {
      console.warn(`No user configured for role "${role}" — skipping.`);
      continue;
    }
    console.log(`${role} screenshots:`);
    const page = await browser.newPage({ viewport: { width, height } });
    await signIn(page, baseUrl, cfg, user);
    for (const guide of guides) {
      await page
        .goto(`${baseUrl}${guide.route}`, { waitUntil: 'networkidle' })
        .catch(() => {});
      await page.waitForTimeout(cfg.settleMs ?? 1200);
      const file = `${role}-${guide.id}.png`;
      await page.screenshot({ path: resolve(outDir, file), fullPage: true });
      console.log(`  ${file}  <- ${guide.route}`);
    }
    await page.close();
  }

  await browser.close();
  console.log(`\nWrote screenshots to ${outDir}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
